using System;using System.IO;using System.Text;using System.Collections.Generic;using Nini.Config;
static class Program{
 static string Hex(string value)=>Convert.ToHexString(Encoding.Unicode.GetBytes(value)).ToLowerInvariant();
 static byte[] Bytes(string line)=>line=="."?Array.Empty<byte>():Convert.FromHexString(line);
 static string Decode(byte[] bytes){string text;Encoding encoding;using(var reader=new StreamReader(new MemoryStream(bytes),Encoding.UTF8,true)){text=reader.ReadToEnd();encoding=reader.CurrentEncoding;}var preamble=encoding.GetPreamble();int bom=bytes.Length>=preamble.Length&&preamble.Length>0&&bytes.AsSpan(0,preamble.Length).SequenceEqual(preamble)?preamble.Length:0;var lines=new List<string>();using(var reader=new StreamReader(new MemoryStream(bytes),Encoding.UTF8,true)){string line;while((line=reader.ReadLine())!=null)lines.Add(Hex(line));}return encoding.CodePage+"|"+bom+"|"+Hex(text)+"|"+lines.Count+"|"+string.Join(",",lines);}
 static string Shape(string path){var ini=new IniConfigSource(path);var sections=new List<string>();foreach(string name in new[]{"Probe"," Probe","Probe ","","Other","probe"}){var section=ini.Configs[name];if(section==null){sections.Add(Hex(name)+"=N");continue;}string[] keys=section.GetKeys();Array.Sort(keys,StringComparer.Ordinal);var entries=new List<string>();foreach(var key in keys)entries.Add(Hex(key)+":"+Hex(section.GetString(key,"")));sections.Add(Hex(name)+"=Y:"+string.Join(",",entries));}return "OK:"+string.Join("|",sections);}
 static string Run(string mode,string line){try{if(mode=="--probe")return Decode(Bytes(line));string path=Encoding.UTF8.GetString(Bytes(line));if(mode=="--config-shape-probe")return Shape(path);if(mode=="--config-probe"){var ini=new IniConfigSource(path);return "OK:"+Hex(ini.Configs["Probe"].GetString("x"));}return Decode(File.ReadAllBytes(path));}catch(Exception e){if(mode=="--config-probe"||mode=="--config-shape-probe")return "ERR:"+Convert.ToHexString(Encoding.UTF8.GetBytes(e.Message)).ToLowerInvariant();uint code=unchecked((uint)e.HResult);return "ERR:"+((code&0xffff0000u)==0x80070000u?code&0xffffu:code);}}
 public static void Main(string[] args){Console.OutputEncoding=new UTF8Encoding(false);string mode=args.Length>0?args[0]:"--probe";string line;while((line=Console.ReadLine())!=null)Console.WriteLine(Run(mode,line));}
}
